} These ports also default to the localhost interface on the remote host. If you need to change this, you can also set the remote host: { "ssh_connections": [ { "host": "192.168.1.10", "port_forwards": [ { "local_port": 8080, "remote_port": 80, "remote_host": "docker-host" } ] } ]
